UPDATE volt_card_order
SET status = 'activated', activated_at = NOW(), activated_by = #{activatedBy}
WHERE order_no = #{orderNo} AND status = 'pending'

UPDATE volt_card_order
SET member_id = #{memberId}
WHERE member_phone = #{phone} AND (member_id IS NULL OR member_id = '')
